170	/**
171	  * @brief  Setup the microcontroller system.
172	  * @retval None
173	  */
174	
175	void SystemInit(void)
176	{
177	
178	  /* Configure the Vector Table location -------------------------------------*/
179	#if defined(USER_VECT_TAB_ADDRESS)
180	  SCB->VTOR = VECT_TAB_BASE_ADDRESS | VECT_TAB_OFFSET;
181	#else
182	  SCB->VTOR = INTVECT_START;
183	#endif  /* USER_VECT_TAB_ADDRESS */
184	
185	  /* RNG reset */
186	  RCC->AHB3RSTSR = RCC_AHB3RSTSR_RNGRSTS;
187	  RCC->AHB3RSTCR = RCC_AHB3RSTCR_RNGRSTC;
188	  /* Deactivate RNG clock */
189	  RCC->AHB3ENCR = RCC_AHB3ENCR_RNGENC;
190	
191	  /* Clear SAU regions */
192	  SAU->RNR = 0;
193	  SAU->RBAR = 0;
194	  SAU->RLAR = 0;
195	  SAU->RNR = 1;
196	  SAU->RBAR = 0;
197	  SAU->RLAR = 0;
198	  SAU->RNR = 2;
199	  SAU->RBAR = 0;
200	  SAU->RLAR = 0;
201	  SAU->RNR = 3;
202	  SAU->RBAR = 0;
203	  SAU->RLAR = 0;
204	  SAU->RNR = 4;
205	  SAU->RBAR = 0;
206	  SAU->RLAR = 0;
207	  SAU->RNR = 5;
208	  SAU->RBAR = 0;
209	  SAU->RLAR = 0;
210	  SAU->RNR = 6;
211	  SAU->RBAR = 0;
212	  SAU->RLAR = 0;
213	  SAU->RNR = 7;
214	  SAU->RBAR = 0;
215	  SAU->RLAR = 0;
216	
217	  /* System configuration setup */
218	  RCC->APB4ENSR2 = RCC_APB4ENSR2_SYSCFGENS;
219	  /* Delay after an RCC peripheral clock enabling */
220	  (void)RCC->APB4ENR2;
221	
222	  /* Set default Vector Table location after system reset or return from Standby */
223	  SYSCFG->INITSVTORCR = SCB->VTOR;
224	
225	  /* Enable VDDADC CLAMP */
226	  PWR->SVMCR3 |= PWR_SVMCR3_ASV;
227	  PWR->SVMCR3 |= PWR_SVMCR3_AVMEN;
228	  /* read back the register to make sure that the transaction has taken place */
229	  (void) PWR->SVMCR3;
230	  /* enable VREF */
231	  RCC->APB4ENR1 |= RCC_APB4ENR1_VREFBUFEN;
232	
233	  /* RCC Fix to lower power consumption */
234	  RCC->APB4ENR2 |= 0x00000010UL;
235	  (void) RCC->APB4ENR2;
236	  RCC->APB4ENR2 &= ~(0x00000010UL);
237	
238	  /* XSPI2 & XSPIM reset                                  */
239	  RCC->AHB5RSTSR = RCC_AHB5RSTSR_XSPIMRSTS | RCC_AHB5RSTSR_XSPI2RSTS;
240	  RCC->AHB5RSTCR = RCC_AHB5RSTCR_XSPIMRSTC | RCC_AHB5RSTCR_XSPI2RSTC;
241	
242	  /* TIM2 reset */
243	  RCC->APB1RSTSR1 = RCC_APB1RSTSR1_TIM2RSTS;
244	  RCC->APB1RSTCR1 = RCC_APB1RSTCR1_TIM2RSTC;
245	  /* Deactivate TIM2 clock */
246	  RCC->APB1ENCR1 = RCC_APB1ENCR1_TIM2ENC;
247	
248	  /* Deactivate GPIOG clock */
249	  RCC->AHB4ENCR = RCC_AHB4ENCR_GPIOGENC;
250	
251	  /* Read back the value to make sure it is written before deactivating SYSCFG */
252	  (void) SYSCFG->INITSVTORCR;
253	  /* Deactivate SYSCFG clock */
254	  RCC->APB4ENCR2 = RCC_APB4ENCR2_SYSCFGENC;
255	
256	#if defined(USER_TZ_SAU_SETUP)
257	  /* SAU/IDAU, FPU and Interrupts secure/non-secure allocation settings */
258	  TZ_SAU_Setup();
259	#endif /* USER_TZ_SAU_SETUP */
260	
261	  /* FPU settings ------------------------------------------------------------*/
262	#if (__FPU_PRESENT == 1) && (__FPU_USED == 1)
263	  SCB->CPACR |= ((3UL << 20U)|(3UL << 22U));  /* set CP10 and CP11 Full Access */
264	
265	  SCB_NS->CPACR |= ((3UL << 20U)|(3UL << 22U));  /* set CP10 and CP11 Full Access */
266	#endif /* __FPU_PRESENT && __FPU_USED */
