269	
270	/**
271	  * @brief  Update SystemCoreClock variable according to Clock Register Values.
272	  *         The SystemCoreClock variable contains the core clock (HCLK), it can
273	  *         be used by the user application to setup the SysTick timer or configure
274	  *         other parameters.
275	  *
276	  * @note   Each time the CPU core clock changes, this function must be called
277	  *         to update SystemCoreClock variable value. Otherwise, any configuration
278	  *         based on this variable will be incorrect.
279	  *
280	  * @note   - The system frequency computed by this function is not the real
281	  *           frequency in the chip. It is calculated based on the predefined
282	  *           constant and the selected clock source:
283	  *
284	  *           - If CPUCLK source is HSI, SystemCoreClock will contain the HSI_VALUE(*)
285	  *
286	  *           - If CPUCLK source is MSI, SystemCoreClock will contain the MSI_VALUE(**)
287	  *
288	  *           - If CPUCLK source is HSE, SystemCoreClock will contain the HSE_VALUE(***)
289	  *
290	  *           - If CPUCLK source is IC1, SystemCoreClock will contain the HSI_VALUE(*)
291	  *             or MSI_VALUE(**) or HSE_VALUE(***) or EXTERNAL_I2S_CLOCK_VALUE (****)
292	  *             multiplied/divided by the PLL factors.
293	  *
294	  *         (*) HSI_VALUE default value is 64 MHz.
295	  *             With the HAL, HSI_VALUE is a constant defined in stm32n6xx_hal_conf.h file
296	  *             but the real value may vary depending on the variations in voltage and temperature.
297	  *
298	  *        (**) MSI_VALUE default value is 4 MHz.
299	  *             With the HAL, MSI_VALUE is a constant defined in stm32n6xx_hal_conf.h file
300	  *             but the real value may vary depending on the variations in voltage and temperature.
301	  *
302	  *       (***) HSE_VALUE default value is 30 MHz.
303	  *             With the HAL, HSE_VALUE is a constant defined in stm32n6xx_hal_conf.h file.
304	  *             User has to ensure that HSE_VALUE is same as the real frequency of the crystal used.
305	  *             Otherwise, this function may have wrong result.
306	  *
307	  *      (****) EXTERNAL_I2S_CLOCK_VALUE default value is 12.288 MHz.
308	  *             With the HAL, EXTERNAL_I2S_CLOCK_VALUE is a constant defined in stm32n6xx_hal_conf.h file.
309	  *             User has to ensure that EXTERNAL_I2S_CLOCK_VALUE is same as the real I2S_CKIN
310	  *             pin frequency. Otherwise, this function may have wrong result.
311	  *
312	  *         - The result of this function could be not correct when using fractional
313	  *           value for HSE crystal.
314	  *
315	  * @retval None
316	  */
317	void SystemCoreClockUpdate(void)
318	{
319	  uint32_t sysclk = 0;
320	  uint32_t pllm = 0;
321	  uint32_t plln = 0;
322	  uint32_t pllfracn = 0;
323	  uint32_t pllp1 = 0;
324	  uint32_t pllp2 = 0;
325	  uint32_t pllcfgr, pllsource, pllbypass, ic_divider;
326	  float_t pllvco;
327	
328	  /* Get CPUCLK source -------------------------------------------------------*/
329	  switch (RCC->CFGR1 & RCC_CFGR1_CPUSWS)
330	  {
331	  case 0:  /* HSI used as system clock source (default after reset) */
332	    sysclk = HSI_VALUE >> ((RCC->HSICFGR & RCC_HSICFGR_HSIDIV) >> RCC_HSICFGR_HSIDIV_Pos);
333	    break;
334	
335	  case RCC_CFGR1_CPUSWS_0:  /* MSI used as system clock source */
336	    if (READ_BIT(RCC->MSICFGR, RCC_MSICFGR_MSIFREQSEL) == 0UL)
337	    {
338	      sysclk = MSI_VALUE;
339	    }
340	    else
341	    {
342	      sysclk = 16000000UL;
343	    }
344	    break;
345	
346	  case RCC_CFGR1_CPUSWS_1:  /* HSE used as system clock source */
347	    sysclk = HSE_VALUE;
348	    break;
349	
350	  case (RCC_CFGR1_CPUSWS_1 | RCC_CFGR1_CPUSWS_0):  /* IC1 used as system clock  source */
351	    /* Get IC1 clock source parameters */
352	    switch (READ_BIT(RCC->IC1CFGR, RCC_IC1CFGR_IC1SEL))
353	    {
354	    case 0:  /* PLL1 selected at IC1 clock source */
355	      pllcfgr = READ_REG(RCC->PLL1CFGR1);
356	      pllsource = pllcfgr & RCC_PLL1CFGR1_PLL1SEL;
357	      pllbypass = pllcfgr & RCC_PLL1CFGR1_PLL1BYP;
358	      if (pllbypass == 0U)
359	      {
360	        pllm = (pllcfgr & RCC_PLL1CFGR1_PLL1DIVM) >>  RCC_PLL1CFGR1_PLL1DIVM_Pos;
361	        plln = (pllcfgr & RCC_PLL1CFGR1_PLL1DIVN) >>  RCC_PLL1CFGR1_PLL1DIVN_Pos;
362	        pllfracn = READ_BIT(RCC->PLL1CFGR2, RCC_PLL1CFGR2_PLL1DIVNFRAC) >>  RCC_PLL1CFGR2_PLL1DIVNFRAC_Pos;
363	        pllcfgr = READ_REG(RCC->PLL1CFGR3);
364	        pllp1 = (pllcfgr & RCC_PLL1CFGR3_PLL1PDIV1) >>  RCC_PLL1CFGR3_PLL1PDIV1_Pos;
365	        pllp2 = (pllcfgr & RCC_PLL1CFGR3_PLL1PDIV2) >>  RCC_PLL1CFGR3_PLL1PDIV2_Pos;
366	      }
367	      break;
368	    case RCC_IC1CFGR_IC1SEL_0:  /* PLL2 selected at IC1 clock source */
369	      pllcfgr = READ_REG(RCC->PLL2CFGR1);
370	      pllsource = pllcfgr & RCC_PLL2CFGR1_PLL2SEL;
371	      pllbypass = pllcfgr & RCC_PLL2CFGR1_PLL2BYP;
372	      if (pllbypass == 0U)
373	      {
374	        pllm = (pllcfgr & RCC_PLL2CFGR1_PLL2DIVM) >>  RCC_PLL2CFGR1_PLL2DIVM_Pos;
375	        plln = (pllcfgr & RCC_PLL2CFGR1_PLL2DIVN) >>  RCC_PLL2CFGR1_PLL2DIVN_Pos;
376	        pllfracn = READ_BIT(RCC->PLL2CFGR2, RCC_PLL2CFGR2_PLL2DIVNFRAC) >>  RCC_PLL2CFGR2_PLL2DIVNFRAC_Pos;
377	        pllcfgr = READ_REG(RCC->PLL2CFGR3);
378	        pllp1 = (pllcfgr & RCC_PLL2CFGR3_PLL2PDIV1) >>  RCC_PLL2CFGR3_PLL2PDIV1_Pos;
379	        pllp2 = (pllcfgr & RCC_PLL2CFGR3_PLL2PDIV2) >>  RCC_PLL2CFGR3_PLL2PDIV2_Pos;
380	      }
381	      break;
382	
383	    case RCC_IC1CFGR_IC1SEL_1:  /* PLL3 selected at IC1 clock source */
384	      pllcfgr = READ_REG(RCC->PLL3CFGR1);
385	      pllsource = pllcfgr & RCC_PLL3CFGR1_PLL3SEL;
386	      pllbypass = pllcfgr & RCC_PLL3CFGR1_PLL3BYP;
387	      if (pllbypass == 0U)
388	      {
389	        pllm = (pllcfgr & RCC_PLL3CFGR1_PLL3DIVM) >>  RCC_PLL3CFGR1_PLL3DIVM_Pos;
390	        plln = (pllcfgr & RCC_PLL3CFGR1_PLL3DIVN) >>  RCC_PLL3CFGR1_PLL3DIVN_Pos;
391	        pllfracn = READ_BIT(RCC->PLL3CFGR2, RCC_PLL3CFGR2_PLL3DIVNFRAC) >>  RCC_PLL3CFGR2_PLL3DIVNFRAC_Pos;
392	        pllcfgr = READ_REG(RCC->PLL3CFGR3);
393	        pllp1 = (pllcfgr & RCC_PLL3CFGR3_PLL3PDIV1) >>  RCC_PLL3CFGR3_PLL3PDIV1_Pos;
394	        pllp2 = (pllcfgr & RCC_PLL3CFGR3_PLL3PDIV2) >>  RCC_PLL3CFGR3_PLL3PDIV2_Pos;
395	      }
396	      break;
397	
398	    default: /* RCC_IC1CFGR_IC1SEL_1 | RCC_IC1CFGR_IC1SEL_0 */  /* PLL4 selected at IC1 clock source */
399	      pllcfgr = READ_REG(RCC->PLL4CFGR1);
400	      pllsource = pllcfgr & RCC_PLL4CFGR1_PLL4SEL;
401	      pllbypass = pllcfgr & RCC_PLL4CFGR1_PLL4BYP;
402	      if (pllbypass == 0U)
403	      {
404	        pllm = (pllcfgr & RCC_PLL4CFGR1_PLL4DIVM) >>  RCC_PLL4CFGR1_PLL4DIVM_Pos;
405	        plln = (pllcfgr & RCC_PLL4CFGR1_PLL4DIVN) >>  RCC_PLL4CFGR1_PLL4DIVN_Pos;
406	        pllfracn = READ_BIT(RCC->PLL4CFGR2, RCC_PLL4CFGR2_PLL4DIVNFRAC) >>  RCC_PLL4CFGR2_PLL4DIVNFRAC_Pos;
407	        pllcfgr = READ_REG(RCC->PLL4CFGR3);
408	        pllp1 = (pllcfgr & RCC_PLL4CFGR3_PLL4PDIV1) >>  RCC_PLL4CFGR3_PLL4PDIV1_Pos;
409	        pllp2 = (pllcfgr & RCC_PLL4CFGR3_PLL4PDIV2) >>  RCC_PLL4CFGR3_PLL4PDIV2_Pos;
410	      }
411	      break;
412	    }
413	
414	    /* Get oscillator frequency used as PLL clock source */
415	    switch (pllsource)
416	    {
417	    case 0:  /* HSI selected as PLL clock source */
418	      sysclk = HSI_VALUE >> ((RCC->HSICFGR & RCC_HSICFGR_HSIDIV) >> RCC_HSICFGR_HSIDIV_Pos);
419	      break;
420	    case RCC_PLL1CFGR1_PLL1SEL_0: /* MSI selected as PLL clock source */
421	      if (READ_BIT(RCC->MSICFGR, RCC_MSICFGR_MSIFREQSEL) == 0UL)
422	      {
423	        sysclk = MSI_VALUE;
424	      }
425	      else
426	      {
427	        sysclk = 16000000UL;
428	      }
429	      break;
430	    case RCC_PLL1CFGR1_PLL1SEL_1: /* HSE selected as PLL clock source */
431	      sysclk = HSE_VALUE;
432	      break;
433	    case (RCC_PLL1CFGR1_PLL1SEL_1 | RCC_PLL1CFGR1_PLL1SEL_0):  /* I2S_CKIN selected as PLL clock source */
434	      sysclk = EXTERNAL_I2S_CLOCK_VALUE;
435	      break;
436	    default:
437	      /* Nothing to do, should not occur */
438	      break;
439	    }
440	
441	    /* Check whether PLL is in bypass mode or not */
442	    if (pllbypass == 0U)
443	    {
444	      /* Compte PLL output frequency (Integer and fractional modes) */
445	      /* PLLVCO = (Freq * (DIVN + (FRACN / 0x1000000) / DIVM) / (DIVP1 * DIVP2)) */
446	      pllvco = ((float_t)sysclk * ((float_t)plln + ((float_t)pllfracn/(float_t)0x1000000UL))) / (float_t)pllm;
447	      sysclk = (uint32_t)((float_t)(pllvco/(((float_t)pllp1) * ((float_t)pllp2))));
448	    }
449	    /* Apply IC1 divider */
450	    ic_divider = (READ_BIT(RCC->IC1CFGR, RCC_IC1CFGR_IC1INT) >> RCC_IC1CFGR_IC1INT_Pos) + 1UL;
451	    sysclk = sysclk / ic_divider;
452	    break;
453	  default:
454	    /* Nothing to do, should not occur */
455	    break;
456	  }
457	
458	  /* Return system clock frequency (CPU frequency) */
459	  SystemCoreClock = sysclk;
460	}
461	
462	/**
463	  * @brief  Secure Non-Secure-Callable function to return the current
464	  *         SystemCoreClock value after SystemCoreClock update.
465	  *         The SystemCoreClock variable contains the CPU core clock, it can
466	  *         be used by the user application to setup the SysTick timer or configure
467	  *         other parameters.
468	  * @retval SystemCoreClock value
469	  */
470	CMSE_NS_ENTRY uint32_t SECURE_SystemCoreClockUpdate(void)
471	{
472	  SystemCoreClockUpdate();
473	
474	  return SystemCoreClock;
475	}
