7	 * contributor license agreements.  See the NOTICE file distributed with
8	 * this work for additional information regarding copyright ownership.  The
9	 * ASF licenses this file to you under the Apache License, Version 2.0 (the
10	 * "License"); you may not use this file except in compliance with the
11	 * License.  You may obtain a copy of the License at
12	 *
13	 *   http://www.apache.org/licenses/LICENSE-2.0
14	 *
15	 * Unless required by applicable law or agreed to in writing, software
16	 * distributed under the License is distributed on an "AS IS" BASIS, WITHOUT
17	 * WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.  See the
18	 * License for the specific language governing permissions and limitations
19	 * under the License.
20	 *
21	 ****************************************************************************/
22	
23	/* The STM32N647X0 has no internal flash.  In DEV boot mode, code is loaded
24	 * directly into SRAM by the ST-Link debugger at 0x34000400.  The first
25	 * 1 KiB of SRAM is reserved for the boot ROM header.
26	 */
27	
28	MEMORY
29	{
30	    sram (rwx) : ORIGIN = 0x34000400, LENGTH = 4193280
31	}
32	
33	OUTPUT_ARCH(arm)
34	ENTRY(_stext)
35	SECTIONS
36	{
37	    .text : {
38	        _stext = ABSOLUTE(.);
39	        *(.vectors)
40	        *(.text .text.*)
41	        *(.fixup)
42	        *(.gnu.warning)
43	        *(.rodata .rodata.*)
44	        *(.gnu.linkonce.t.*)
45	        *(.glue_7)
46	        *(.glue_7t)
47	        *(.got)
48	        *(.gcc_except_table)
49	        *(.gnu.linkonce.r.*)
50	        _etext = ABSOLUTE(.);
51	    } > sram
52	
53	    .init_section : {
54	        _sinit = ABSOLUTE(.);
55	        KEEP(*(SORT_BY_INIT_PRIORITY(.init_array.*) SORT_BY_INIT_PRIORITY(.ctors.*)))
56	        KEEP(*(.init_array EXCLUDE_FILE(*crtbegin.o *crtbegin?.o *crtend.o *crtend?.o) .ctors))
57	        _einit = ABSOLUTE(.);
58	    } > sram
59	
60	    .ARM.extab : {
61	        *(.ARM.extab*)
62	    } > sram
63	
64	    __exidx_start = ABSOLUTE(.);
65	    .ARM.exidx : {
66	        *(.ARM.exidx*)
67	    } > sram
68	    __exidx_end = ABSOLUTE(.);
69	
70	    .data : {
71	        _eronly = ABSOLUTE(.);
72	        _sdata = ABSOLUTE(.);
73	        *(.data .data.*)
74	        *(.gnu.linkonce.d.*)
75	        CONSTRUCTORS
76	        . = ALIGN(4);
77	        _edata = ABSOLUTE(.);
78	    } > sram
79	
80	    .bss : {
81	        _sbss = ABSOLUTE(.);
82	        *(.bss .bss.*)
83	        *(.gnu.linkonce.b.*)
84	        *(COMMON)
85	        . = ALIGN(4);
86	        _ebss = ABSOLUTE(.);
87	    } > sram
88	
89	    /* Stabs debugging sections. */
90	
91	    .stab 0 : { *(.stab) }
92	    .stabstr 0 : { *(.stabstr) }
93	    .stab.excl 0 : { *(.stab.excl) }
94	    .stab.exclstr 0 : { *(.stab.exclstr) }
95	    .stab.index 0 : { *(.stab.index) }
96	    .stab.indexstr 0 : { *(.stab.indexstr) }
97	    .comment 0 : { *(.comment) }
98	    .debug_abbrev 0 : { *(.debug_abbrev) }
99	    .debug_info 0 : { *(.debug_info) }
100	    .debug_line 0 : { *(.debug_line) }
101	    .debug_pubnames 0 : { *(.debug_pubnames) }
102	    .debug_aranges 0 : { *(.debug_aranges) }
103	}
104

