27	// This XSPI driver is currently configured to run in 1-line (SPI) mode.
28	// It uses the mp_qspi_proto_t QSPI protocol and translates quad-commands
29	// into 1-line commands.
30	
31	#include <string.h>
32	#include "py/mperrno.h"
33	#include "py/mphal.h"
34	#include "xspi.h"
35	
36	#if defined(MICROPY_HW_XSPIFLASH_SIZE_BITS_LOG2)
37	
38	#ifndef MICROPY_HW_XSPI_PRESCALER
39	#define MICROPY_HW_XSPI_PRESCALER (4) // F_CLK = F_AHB/4
40	#endif
41	
42	#ifndef MICROPY_HW_XSPI_CS_HIGH_CYCLES
43	#define MICROPY_HW_XSPI_CS_HIGH_CYCLES (2) // nCS stays high for 4 cycles
44	#endif
45	
46	// Currently hard-coded to use XSPI2 instance.
47	#define XSPIx (XSPI2)
48	
49	// For XSPI2, PN0 through PN12.
50	#define XSPI2_AF (9)
51	
52	typedef struct _xspi_flash_t {
53	    XSPI_TypeDef *xspi;
54	    uintptr_t xip_base;
55	} xspi_flash_t;
