58	    .xspi = XSPI1,
59	    .xip_base = 0x90000000,
60	};
61	
62	const xspi_flash_t xspi_flash2 = {
63	    .xspi = XSPI2,
64	    .xip_base = 0x70000000,
65	};
66	
67	static bool xspi_dtr_enabled = false;
68	
69	#ifdef pyb_pin_FLASH_RESET
70	// Can't rely on SysTick being available, so use a busy loop for delays.
71	// The timing here is approximate and assumes a CPU frequency of 800MHz.
72	static void xspi_delay_us(unsigned int us) {
73	    while (us--) {
74	        for (unsigned int i = 0; i < 800; ++i) {
75	            __NOP();
76	        }
77	    }
78	}
79	#endif
