81	static inline void mp_hal_pin_config_alt_speed(mp_hal_pin_obj_t pin, uint32_t pull, uint32_t alt, uint32_t speed) {
82	    mp_hal_pin_config(pin, MP_HAL_PIN_MODE_ALT, pull, alt);
83	    mp_hal_pin_config_speed(pin, speed);
84	}
