94	void xspi_init(void) {
95	    // Configure XSPI pins.
96	    mp_hal_pin_config_alt_speed(pyb_pin_XSPIM_P2_CS, MP_HAL_PIN_PULL_NONE, XSPI2_AF, MP_HAL_PIN_SPEED_VERY_HIGH);
97	    mp_hal_pin_config_alt_speed(pyb_pin_XSPIM_P2_SCK, MP_HAL_PIN_PULL_NONE, XSPI2_AF, MP_HAL_PIN_SPEED_VERY_HIGH);
98	    mp_hal_pin_config_alt_speed(pyb_pin_XSPIM_P2_DQS, MP_HAL_PIN_PULL_NONE, XSPI2_AF, MP_HAL_PIN_SPEED_VERY_HIGH);
99	    mp_hal_pin_config_alt_speed(pyb_pin_XSPIM_P2_IO0, MP_HAL_PIN_PULL_NONE, XSPI2_AF, MP_HAL_PIN_SPEED_VERY_HIGH);
100	    mp_hal_pin_config_alt_speed(pyb_pin_XSPIM_P2_IO1, MP_HAL_PIN_PULL_NONE, XSPI2_AF, MP_HAL_PIN_SPEED_VERY_HIGH);
101	    mp_hal_pin_config_alt_speed(pyb_pin_XSPIM_P2_IO2, MP_HAL_PIN_PULL_NONE, XSPI2_AF, MP_HAL_PIN_SPEED_VERY_HIGH);
102	    mp_hal_pin_config_alt_speed(pyb_pin_XSPIM_P2_IO3, MP_HAL_PIN_PULL_NONE, XSPI2_AF, MP_HAL_PIN_SPEED_VERY_HIGH);
103	    mp_hal_pin_config_alt_speed(pyb_pin_XSPIM_P2_IO4, MP_HAL_PIN_PULL_NONE, XSPI2_AF, MP_HAL_PIN_SPEED_VERY_HIGH);
104	    mp_hal_pin_config_alt_speed(pyb_pin_XSPIM_P2_IO5, MP_HAL_PIN_PULL_NONE, XSPI2_AF, MP_HAL_PIN_SPEED_VERY_HIGH);
105	    mp_hal_pin_config_alt_speed(pyb_pin_XSPIM_P2_IO6, MP_HAL_PIN_PULL_NONE, XSPI2_AF, MP_HAL_PIN_SPEED_VERY_HIGH);
106	    mp_hal_pin_config_alt_speed(pyb_pin_XSPIM_P2_IO7, MP_HAL_PIN_PULL_NONE, XSPI2_AF, MP_HAL_PIN_SPEED_VERY_HIGH);
107	
108	    LL_AHB5_GRP1_ForceReset(LL_AHB5_GRP1_PERIPH_XSPIM);
109	    LL_AHB5_GRP1_ForceReset(LL_AHB5_GRP1_PERIPH_XSPI1);
110	    LL_AHB5_GRP1_ForceReset(LL_AHB5_GRP1_PERIPH_XSPI2);
111	    LL_AHB5_GRP1_ForceReset(LL_AHB5_GRP1_PERIPH_XSPI3);
112	
113	    LL_AHB5_GRP1_ReleaseReset(LL_AHB5_GRP1_PERIPH_XSPIM);
114	    LL_AHB5_GRP1_ReleaseReset(LL_AHB5_GRP1_PERIPH_XSPI1);
115	    LL_AHB5_GRP1_ReleaseReset(LL_AHB5_GRP1_PERIPH_XSPI2);
116	    LL_AHB5_GRP1_ReleaseReset(LL_AHB5_GRP1_PERIPH_XSPI3);
117	
118	    LL_RCC_SetXSPIClockSource(LL_RCC_XSPI1_CLKSOURCE_HCLK);
119	    LL_RCC_SetXSPIClockSource(LL_RCC_XSPI2_CLKSOURCE_HCLK);
120	
121	    LL_AHB5_GRP1_EnableClock(LL_AHB5_GRP1_PERIPH_XSPIM);
122	    LL_AHB5_GRP1_EnableClock(LL_AHB5_GRP1_PERIPH_XSPI1);
123	    LL_AHB5_GRP1_EnableClock(LL_AHB5_GRP1_PERIPH_XSPI2);
124	
125	    // Configure XSPIM in direct mode.
126	    XSPI1->CR &= ~XSPI_CR_EN;
127	    XSPI2->CR &= ~XSPI_CR_EN;
128	    XSPIM->CR = 0;
129	
130	    // Configure the XSPIx peripheral.
131	
132	    XSPIx->CR =
133	        3 << XSPI_CR_FTHRES_Pos // 4 byte must be available to read/write
134	            | 0 << XSPI_CR_MSEL_Pos // FLASH 0 selected
135	            | 0 << XSPI_CR_CSSEL_Pos // use NCS1 as chip select
136	            | 0 << XSPI_CR_DMM_Pos // dual-memory mode disabled
137	            | 1 << XSPI_CR_TCEN_Pos // time-out counter enabled
138	            | 0 << XSPI_CR_DMAEN_Pos // DMA disabled
139	            | 0 << XSPI_CR_ABORT_Pos // no abort request
140	            | 0 << XSPI_CR_EN_Pos // disabled
141	    ;
142	
143	    XSPIx->DCR1 =
144	        1 << XSPI_DCR1_MTYP_Pos // Macronix mode
145	            | (MICROPY_HW_XSPIFLASH_SIZE_BITS_LOG2 - 3 - 1) << XSPI_DCR1_DEVSIZE_Pos
146	            | (MICROPY_HW_XSPI_CS_HIGH_CYCLES - 1) << XSPI_DCR1_CSHT_Pos
147	            | 0 << XSPI_DCR1_FRCK_Pos // CLK is not free running
148	            | 0 << XSPI_DCR1_CKMODE_Pos // CLK idles at low state
149	    ;
150	
151	    XSPIx->DCR2 =
152	        0 << XSPI_DCR2_WRAPSIZE_Pos // separate wrap reads are not supported by the memory
153	            | (MICROPY_HW_XSPI_PRESCALER - 1) << XSPI_DCR2_PRESCALER_Pos
154	    ;
155	
156	    XSPIx->DCR3 =
157	        0
158	        // 10 << XSPI_DCR3_CSBOUND_Pos // transaction boundary at 1024
159	    ;
160	
161	    XSPIx->DCR4 =
162	        0 << XSPI_DCR4_REFRESH_Pos // refresh disabled (it's non-volatile memory)
163	    ;
164	
165	    XSPIx->TCR = 0;
166	
167	    // Enable the XSPI peripheral.
168	    XSPIx->CR |= XSPI_CR_EN;
169	
170	    // XSPIM init
171	    XSPI1->CR &= ~(1 << XSPI_CR_EN_Pos);
172	    XSPI2->CR &= ~(1 << XSPI_CR_EN_Pos);
173	    XSPIM->CR = 0; // can also be (1 << 4) to pass through CS signal
174	    XSPIx->CR |= 1 << XSPI_CR_EN_Pos;
175	
176	    #ifdef pyb_pin_FLASH_RESET
177	    // Reset SPI flash to make sure it's in a known state (SPI mode).
178	    mp_hal_pin_output(pyb_pin_FLASH_RESET);
179	    mp_hal_pin_low(pyb_pin_FLASH_RESET);
180	    xspi_delay_us(1000);
181	    mp_hal_pin_high(pyb_pin_FLASH_RESET);
182	    xspi_delay_us(10000);
183	    #endif
184	
185	    // Enable memory-mapped mode.
186	    // Can select either SPI or DTR mode.
187	    if (1) {
188	        xspi_switch_to_dtr();
189	        xspi_memory_map_888();
190	    } else {
191	        xspi_memory_map_111();
192	    }
193	}
