203	static int xspi_read_111_ext(uint8_t cmd, bool addr_enabled, uint32_t addr, size_t len, uint8_t *dest) {
204	    uint32_t admode = addr_enabled ? 1 : 0;
205	    XSPIx->CR = (XSPIx->CR & ~XSPI_CR_FMODE_Msk) | 1 << XSPI_CR_FMODE_Pos; // indirect read mode
206	    XSPIx->CCR =
207	        1 << XSPI_CCR_DMODE_Pos // data on 1 line
208	            | 3 << XSPI_CCR_ADSIZE_Pos // 32-bit address size
209	            | admode << XSPI_CCR_ADMODE_Pos // address on 1 line, or disabled
210	            | 1 << XSPI_CCR_IMODE_Pos // instruction on 1 line
211	    ;
212	    XSPIx->TCR = 0 << XSPI_TCR_DCYC_Pos; // 0 dummy cycles
213	    XSPIx->DLR = len - 1; // number of bytes to read
214	    XSPIx->IR = cmd; // read opcode (triggers the start of the transaction if address disabled)
215	    if (addr_enabled) {
216	        XSPIx->AR = addr; // triggers the start of the transaction
217	    }
218	
219	    #if 0 // untested code
220	    // Read in the data 4 bytes at a time if dest is aligned.
221	    if (((uintptr_t)dest & 3) == 0) {
222	        while (len >= 4) {
223	            while (!(XSPIx->SR & XSPI_SR_FTF)) {
224	                if (XSPIx->SR & XSPI_SR_TEF) {
225	                    return -MP_EIO;
226	                }
227	            }
228	            *(uint32_t *)dest = XSPIx->DR;
229	            dest += 4;
230	            len -= 4;
231	        }
232	    }
233	    #endif
234	
235	    // Read in data 1 byte at a time.
236	    while (len--) {
237	        while (!((XSPIx->SR >> XSPI_SR_FLEVEL_Pos) & 0x3f)) {
238	            if (XSPIx->SR & XSPI_SR_TEF) {
239	                return -MP_EIO;
240	            }
241	        }
242	        *dest++ = *(volatile uint8_t *)&XSPIx->DR;
243	    }
244	
245	    XSPIx->FCR = XSPI_FCR_CTCF; // clear TC flag
246	
247	    return 0;
248	}
249	
250	static int xspi_write_111_ext(uint8_t cmd, bool addr_enabled, uint32_t addr, size_t len, const uint8_t *src) {
251	    uint32_t dmode = len == 0 ? 0 : 1;
252	    uint32_t admode = addr_enabled ? 1 : 0;
253	
254	    // Configure and start the transfer.
255	    // Transfer starts with IR write if no address or data, with AR write if no data,
256	    // otherwise with DR write.
257	
258	    XSPIx->CR = (XSPIx->CR & ~XSPI_CR_FMODE_Msk) | 0 << XSPI_CR_FMODE_Pos; // indirect write mode
259	    XSPIx->CCR =
260	        dmode << XSPI_CCR_DMODE_Pos // data on 1 line, or disabled
261	            | 3 << XSPI_CCR_ADSIZE_Pos // 32-bit address size
262	            | admode << XSPI_CCR_ADMODE_Pos // address on 1 line, or disabled
263	            | 1 << XSPI_CCR_IMODE_Pos // instruction on 1 line
264	    ;
265	    XSPIx->TCR = 0 << XSPI_TCR_DCYC_Pos; // 0 dummy cycles
266	    if (len != 0) {
267	        XSPIx->DLR = len - 1;
268	    }
269	    XSPIx->IR = cmd; // write opcode
270	    if (addr_enabled) {
271	        XSPIx->AR = addr; // address
272	    }
273	
274	    // Write out the data one byte at a time
275	    while (len--) {
276	        while (!(XSPIx->SR & XSPI_SR_FTF)) {
277	            if (XSPIx->SR & XSPI_SR_TEF) {
278	                return -MP_EIO;
279	            }
280	        }
281	        *(volatile uint8_t *)&XSPIx->DR = *src++;
282	    }
283	
284	    // Wait for write to finish
285	    while (!(XSPIx->SR & XSPI_SR_TCF)) {
286	        if (XSPIx->SR & XSPI_SR_TEF) {
287	            return -MP_EIO;
288	        }
289	    }
290	
291	    XSPIx->FCR = XSPI_FCR_CTCF; // clear TC flag
292	
293	    // Wait for peripheral to return to idle.
294	    while (XSPIx->SR & XSPI_SR_BUSY) {
295	    }
296	
297	    return 0;
298	}
