300	static int xspi_read_888_dtr_ext(uint16_t cmd, bool addr_enabled, uint32_t addr, uint32_t num_dummy, size_t len, uint8_t *dest) {
301	    uint32_t admode = addr_enabled ? 4 : 0;
302	
303	    // Configure and start the transfer.
304	    // Transfer starts with IR write if no address, otherwise with AR write.
305	
306	    XSPIx->CR = (XSPIx->CR & ~XSPI_CR_FMODE_Msk) | 1 << XSPI_CR_FMODE_Pos; // indirect read mode
307	    XSPIx->CCR =
308	        1 << XSPI_CCR_DQSE_Pos // DQS enabled
309	            | 1 << XSPI_CCR_DDTR_Pos // data DTR enabled
310	            | 4 << XSPI_CCR_DMODE_Pos // data on 8 lines
311	            | 3 << XSPI_CCR_ADSIZE_Pos // 32-bit address size
312	            | 1 << XSPI_CCR_ADDTR_Pos // address DTR enabled
313	            | admode << XSPI_CCR_ADMODE_Pos // address on 8 lines, or disabled
314	            | 1 << XSPI_CCR_ISIZE_Pos // 16-bit instruction
315	            | 1 << XSPI_CCR_IDTR_Pos // instruction DTR enabled
316	            | 4 << XSPI_CCR_IMODE_Pos // instruction on 8 lines
317	    ;
318	    XSPIx->TCR = num_dummy << XSPI_TCR_DCYC_Pos; // N dummy cycles
319	    XSPIx->DLR = len - 1;
320	    XSPIx->IR = cmd; // read opcode
321	    if (addr_enabled) {
322	        XSPIx->AR = addr; // address
323	    }
324	
325	    // Read in data 1 byte at a time.
326	    while (len--) {
327	        while (!((XSPIx->SR >> XSPI_SR_FLEVEL_Pos) & 0x3f)) {
328	            if (XSPIx->SR & XSPI_SR_TEF) {
329	                return -MP_EIO;
330	            }
331	        }
332	        *dest++ = *(volatile uint8_t *)&XSPIx->DR;
333	    }
334	
335	    XSPIx->FCR = XSPI_FCR_CTCF; // clear TC flag
336	
337	    return 0;
338	}
339	
340	static int xspi_write_888_dtr_ext(uint16_t cmd, bool addr_enabled, uint32_t addr, size_t len, const uint8_t *src) {
341	    uint32_t dmode = len == 0 ? 0 : 4;
342	    uint32_t admode = addr_enabled ? 4 : 0;
343	
344	    // Configure and start the transfer.
345	    // Transfer starts with IR write if no address or data, with AR write if no data,
346	    // otherwise with DR write.
347	
348	    XSPIx->CR = (XSPIx->CR & ~XSPI_CR_FMODE_Msk) | 0 << XSPI_CR_FMODE_Pos; // indirect write mode
349	    XSPIx->CCR =
350	        1 << XSPI_CCR_DDTR_Pos // data DTR enabled
351	            | dmode << XSPI_CCR_DMODE_Pos // data on 8 lines, or disabled
352	            | 3 << XSPI_CCR_ADSIZE_Pos // 32-bit address size
353	            | 1 << XSPI_CCR_ADDTR_Pos // address DTR enabled
354	            | admode << XSPI_CCR_ADMODE_Pos // address on 8 lines, or disabled
355	            | 1 << XSPI_CCR_ISIZE_Pos // 16-bit instruction
356	            | 1 << XSPI_CCR_IDTR_Pos // instruction DTR enabled
357	            | 4 << XSPI_CCR_IMODE_Pos // instruction on 8 lines
358	    ;
359	    XSPIx->TCR = 0 << XSPI_TCR_DCYC_Pos; // 0 dummy cycles
360	    if (len != 0) {
361	        XSPIx->DLR = len - 1;
362	    }
363	    XSPIx->IR = cmd; // write opcode
364	    if (addr_enabled) {
365	        XSPIx->AR = addr; // address
366	    }
367	
368	    // Write out the data one byte at a time
369	    while (len--) {
370	        while (!(XSPIx->SR & XSPI_SR_FTF)) {
371	            if (XSPIx->SR & XSPI_SR_TEF) {
372	                return -MP_EIO;
373	            }
374	        }
375	        *(volatile uint8_t *)&XSPIx->DR = *src++;
376	    }
377	
378	    // Wait for write to finish
379	    while (!(XSPIx->SR & XSPI_SR_TCF)) {
380	        if (XSPIx->SR & XSPI_SR_TEF) {
381	            return -MP_EIO;
382	        }
383	    }
384	
385	    XSPIx->FCR = XSPI_FCR_CTCF; // clear TC flag
386	
387	    // Wait for peripheral to return to idle.
388	    while (XSPIx->SR & XSPI_SR_BUSY) {
389	    }
390	
391	    return 0;
392	}
393	
394	static void xspi_memory_map_111(void) {
395	    XSPIx->CCR =
396	        1 << XSPI_CCR_DMODE_Pos // data on 1 line
397	            | 3 << XSPI_CCR_ADSIZE_Pos // 32-bit address
398	            | 1 << XSPI_CCR_ADMODE_Pos // address on 1 line
399	            | 1 << XSPI_CCR_IMODE_Pos // instruction on 1 line
400	    ;
401	
402	    XSPIx->TCR = 0 << XSPI_TCR_DCYC_Pos; // no dummy cycles
403	    XSPIx->IR = 0x13; // READ4B
404	    XSPIx->LPTR = 1024; // timeout period in number of CLK cycles
405	
406	    // Enable the XSPI peripheral in memory-mapped mode.
407	    XSPIx->CR = (XSPIx->CR & ~XSPI_CR_FMODE_Msk) | 3 << XSPI_CR_FMODE_Pos;
408	}
409	
410	static void xspi_memory_map_888(void) {
411	    XSPIx->CCR =
412	        1 << XSPI_CCR_DQSE_Pos // DQS enabled
413	            | 1 << XSPI_CCR_DDTR_Pos // data DTR enabled
414	            | 4 << XSPI_CCR_DMODE_Pos // data on 8 lines
415	            | 3 << XSPI_CCR_ADSIZE_Pos // 32-bit address
416	            | 1 << XSPI_CCR_ADDTR_Pos // address DTR enabled
417	            | 4 << XSPI_CCR_ADMODE_Pos // address on 8 lines
418	            | 1 << XSPI_CCR_ISIZE_Pos // 16-bit instruction
419	            | 1 << XSPI_CCR_IDTR_Pos // instruction DTR enabled
420	            | 4 << XSPI_CCR_IMODE_Pos // instruction on 8 lines
421	    ;
422	
423	    XSPIx->TCR = 20 << XSPI_TCR_DCYC_Pos; // 20 dummy cycles for reading (minimum, flash may insert more by holding DQS low)
424	    XSPIx->IR = 0xee11; // octal DTR read mode (8DTRD)
425	    XSPIx->LPTR = 1024; // timeout period in number of CLK cycles
426	
427	    // Enable the XSPI peripheral in memory-mapped mode.
428	    XSPIx->CR = (XSPIx->CR & ~XSPI_CR_FMODE_Msk) | 3 << XSPI_CR_FMODE_Pos;
429	}
430	
431	static void xspi_memory_map_exit(void) {
432	    // Abort any ongoing transfer if peripheral is busy.
433	    if (XSPIx->SR & XSPI_SR_BUSY) {
434	        XSPIx->CR |= XSPI_CR_ABORT;
435	        while (!(XSPIx->SR & XSPI_SR_TCF)) {
436	        }
437	        XSPIx->FCR = XSPI_FCR_CTCF; // clear TC flag
438	        while (XSPIx->SR & XSPI_SR_BUSY) {
439	        }
440	    }
441	    XSPIx->CR = (XSPIx->CR & ~XSPI_CR_FMODE_Msk) | 0 << XSPI_CR_FMODE_Pos; // indirect write mode
442	}
443	
444	void xspi_switch_to_dtr(void) {
445	    uint8_t buf[4];
446	
447	    // WREN.
448	    xspi_write_111_ext(0x06, false, 0, 0, NULL);
449	
450	    // Wait WEL=1, with small timeout.
451	    for (unsigned int i = 0; i < 100; ++i) {
452	        xspi_read_111_ext(0x05, false, 0, 1, buf);
453	        if (buf[0] & 2) {
454	            break;
455	        }
456	    }
457	
458	    // Switch to DOPI DTR mode.
459	    buf[0] = 2;
460	    xspi_write_111_ext(0x72, true, 0x00000000, 1, buf);
461	
462	    xspi_dtr_enabled = true;
463	}
464	
465	void xspi_switch_to_spi(void) {
466	    uint8_t buf[4];
467	
468	    // WREN.
469	    xspi_write_888_dtr_ext(0x06f9, false, 0, 0, NULL);
470	
471	    // Wait WEL=1, with small timeout.
472	    for (unsigned int i = 0; i < 100; ++i) {
473	        xspi_read_111_ext(0x05, false, 0, 1, buf);
474	        if (buf[0] & 2) {
475	            break;
476	        }
477	    }
478	
479	    // Switch to SPI mode.
480	    buf[0] = 0;
481	    buf[1] = 0;
482	    xspi_write_888_dtr_ext(0x728d, true, 0x00000000, 2, buf);
483	
484	    xspi_dtr_enabled = false;
485	}
486	
487	static int xspi_ioctl(void *self_in, uint32_t cmd, uintptr_t arg) {
488	    xspi_flash_t *self = self_in;
489	    switch (cmd) {
490	        case MP_QSPI_IOCTL_INIT:
491	            // XSPI must be manually initialise by calling `xspi_init()` at boot.
492	            // Here, just determine if it's in SPI or DTR mode.
493	            xspi_dtr_enabled = XSPIx->IR == 0xee11;
494	            break;
495	        case MP_QSPI_IOCTL_BUS_ACQUIRE:
496	            xspi_memory_map_exit();
497	            break;
498	        case MP_QSPI_IOCTL_BUS_RELEASE:
499	            if (xspi_dtr_enabled) {
500	                xspi_memory_map_888();
501	            } else {
502	                xspi_memory_map_111();
503	            }
504	            break;
505	        case MP_QSPI_IOCTL_MEMORY_MODIFIED: {
506	            uintptr_t *addr_len = (uintptr_t *)arg;
507	            volatile void *addr = (volatile void *)(self->xip_base + addr_len[0]);
508	            size_t len = addr_len[1];
509	            SCB_InvalidateICache_by_Addr(addr, len);
510	            SCB_InvalidateDCache_by_Addr(addr, len);
511	            break;
512	        }
513	    }
514	    return 0; // success
515	}
516	
517	// These commands may be passed to this function.
518	#define CMD_WREN        (0x06)
519	#define CMD_RSTEN       (0x66)
520	#define CMD_RESET       (0x99)
521	#define CMD_SLEEP       (0xb9)
522	#define CMD_AWAKE       (0xab)
523	static int xspi_write_cmd_data(void *self_in, uint8_t cmd, size_t len, uint32_t data) {
524	    if (xspi_dtr_enabled) {
525	        uint16_t cmd16 = 0;
526	        if (cmd == CMD_WREN) {
527	            cmd16 = 0x06f9;
528	        } else if (cmd == CMD_SLEEP) {
529	            cmd16 = 0xb946;
530	        } else if (cmd == CMD_AWAKE) {
531	            cmd16 = 0xab54;
532	        }
533	        return xspi_write_888_dtr_ext(cmd16, false, 0, len, (const uint8_t *)&data);
534	    }
535	    return xspi_write_111_ext(cmd, false, 0, len, (const uint8_t *)&data);
536	}
537	
538	// These commands may be passed to this function.
539	#define CMD_WRITE       (0x02)
540	#define CMD_WRITE_32    (0x12)
541	#define CMD_SEC_ERASE   (0x20)
542	#define CMD_SEC_ERASE_32 (0x21)
543	static int xspi_write_cmd_addr_data(void *self_in, uint8_t cmd, uint32_t addr, size_t len, const uint8_t *src) {
544	    // Convert 24-bit address commands to 32-bit address commands.
545	    if (cmd == CMD_WRITE) {
546	        cmd = CMD_WRITE_32;
547	    } else if (cmd == CMD_SEC_ERASE) {
548	        cmd = CMD_SEC_ERASE_32;
549	    }
550	    if (xspi_dtr_enabled) {
551	        uint16_t cmd16 = 0;
552	        if (cmd == CMD_WRITE_32) {
553	            cmd16 = 0x12ed;
554	        } else if (cmd == CMD_SEC_ERASE_32) {
555	            cmd16 = 0x21de;
556	        }
557	        return xspi_write_888_dtr_ext(cmd16, true, addr, len, src);
558	    }
559	    return xspi_write_111_ext(cmd, true, addr, len, src);
560	}
561	
562	// These commands may be passed to this function.
563	#define CMD_RDSR        (0x05)
564	#define CMD_RD_DEVID    (0x9f)
565	static int xspi_read_cmd(void *self_in, uint8_t cmd, size_t len, uint32_t *dest) {
566	    (void)self_in;
567	    if (xspi_dtr_enabled) {
568	        uint16_t cmd16 = 0;
569	        uint32_t num_dummy = 0;
570	        if (cmd == CMD_RDSR) {
571	            cmd16 = 0x05fa;
572	            num_dummy = 4;
573	            len = 2;
574	        } else if (cmd == CMD_RD_DEVID) {
575	            // TODO this doesn't really work, because result is in STR format.
576	            cmd16 = 0x9f60;
577	            num_dummy = 4;
578	        }
579	        return xspi_read_888_dtr_ext(cmd16, true, 0, num_dummy, len, (uint8_t *)dest);
580	    }
581	    return xspi_read_111_ext(cmd, false, 0, len, (uint8_t *)dest);
582	}
583	
584	static int xspi_direct_read(void *self_in, uint32_t addr, size_t len, uint8_t *dest) {
585	    xspi_flash_t *self = self_in;
586	    memcpy(dest, (const void *)(self->xip_base + addr), len);
587	    return 0;
588	}
589	
590	const mp_qspi_proto_t xspi_proto = {
591	    .ioctl = xspi_ioctl,
592	    .write_cmd_data = xspi_write_cmd_data,
593	    .write_cmd_addr_data = xspi_write_cmd_addr_data,
594	    .read_cmd = xspi_read_cmd,
595	    .read_cmd_qaddr_qdata = NULL, // unused because .direct_read is set below, and caching is disabled
596	    .direct_read = xspi_direct_read,
597	};
598	
599	#endif // defined(MICROPY_HW_XSPIFLASH_SIZE_BITS_LOG2)
600

