/****************************************************************************
 * First Stage Boot Loader (FSBL) for ATK-DNN647 board.
 *
 * This FSBL runs from SRAM2 at 0x34180400 after the STM32N6 boot ROM
 * loads it from external flash.  It performs the following tasks:
 *
 *   1. Configure VDD voltage domains (VDDIO2/3/4)
 *   2. Configure SMPS supply and voltage scaling
 *   3. Initialize XSPI2 flash controller (MX25UM25645G, 32MB)
 *   4. Switch flash to DTR (Double Transfer Rate) mode
 *   5. Enable memory-mapped mode for XIP at 0x70000000
 *   6. Jump to the NuttX application at 0x70080000
 *
 * Reference: demo/atk-dnn647-micropython/ports/stm32/boards/ATK_DNN647/board.c
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdint.h>
#include <string.h>

#include "arm_internal.h"
#include "stm32.h"
#include "hardware/stm32n6xxx_rcc.h"
#include "hardware/stm32n6xxx_pwr.h"
#include "hardware/stm32n6xxx_bsec.h"
#include "hardware/stm32n6xxx_syscfg.h"
#include "hardware/stm32n6xxx_xspi.h"
#include "hardware/stm32n6xxx_gpio.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Application entry point in external flash (XIP) */

#define APPLICATION_ADDR  0x70080000

/* XSPI2 configuration for MX25UM25645G (32MB) */

#define XSPI_FLASH_SIZE   (32 * 1024 * 1024)
#define XSPI_FLASH_SIZE_BITS_LOG2  28  /* log2(32MB * 8 bits) = 28 */

/* XSPI2 pins: PN0-PN12, AF9 */

#define XSPI2_AF  9

/* OTP fuse for VDDIO3 low voltage mode */

#define BSEC_HW_CONFIG_ID       124
#define BSEC_HWS_HSLV_VDDIO3   (1 << 15)

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* XSPI flash command definitions for MX25UM25645G */

#define CMD_WREN          0x06
#define CMD_RDSR          0x05
#define CMD_WRITE_32      0x12
#define CMD_SEC_ERASE_32  0x21
#define CMD_READ4B        0x13

/* DTR mode commands */

#define CMD_WREN_DTR      0x06f9
#define CMD_RDSR_DTR      0x05fa
#define CMD_8DTRD         0xee11
#define CMD_WRITE_DTR     0x12ed
#define CMD_ERASE_DTR     0x21de

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

static void fsbl_config_vdd(void);
static void fsbl_config_power(void);
static void xspi_pin_config(void);
static void xspi_init(void);
static void xspi_write_111(uint8_t cmd, uint32_t addr, bool addr_en,
                            const uint8_t *data, size_t len);
static void xspi_read_111(uint8_t cmd, uint32_t addr, bool addr_en,
                           uint8_t *data, size_t len);
static void xspi_write_888_dtr(uint16_t cmd, uint32_t addr, bool addr_en,
                                const uint8_t *data, size_t len);
static void xspi_read_888_dtr(uint16_t cmd, uint32_t addr, bool addr_en,
                               uint32_t dummy, uint8_t *data, size_t len);
static void xspi_switch_to_dtr(void);
static void xspi_memory_map_888(void);
static void fsbl_jump_to_app(uint32_t app_addr);

/****************************************************************************
 * Private Data
 ****************************************************************************/

/* Nothing needed */

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: fsbl_config_vdd
 *
 * Description:
 *   Configure VDD voltage domains for the DNN647 board.
 *
 ****************************************************************************/

static void fsbl_config_vdd(void)
{
  uint32_t fuse;

  /* Enable PWR, BSEC and SYSCFG clocks */

  modifyreg32(STM32_RCC_AHB4ENSR, 0, RCC_AHB4ENSR_PWR);
  modifyreg32(STM32_RCC_APB4ENSR2, 0, RCC_APB4ENSR2_BSEC);
  modifyreg32(STM32_RCC_APB4ENSR2, 0, RCC_APB4ENSR2_SYSCFG);

  /* Program high speed IO optimization fuses if not already set */

  fuse = getreg32(STM32_BSEC_OTP(BSEC_HW_CONFIG_ID));
  if ((fuse & BSEC_HWS_HSLV_VDDIO3) == 0)
    {
      putreg32(fuse | BSEC_HWS_HSLV_VDDIO3,
               STM32_BSEC_OTP(BSEC_HW_CONFIG_ID));
    }

  /* Enable VDD ADC */

  modifyreg32(STM32_PWR_SVMCR3, 0, PWR_SVMCR3_ASV | PWR_SVMCR3_AVMEN);

  /* Configure VDDIO2 (3.3V) */

  modifyreg32(STM32_PWR_CR11, 0, PWR_CR11_VDDIO2SV);
  modifyreg32(STM32_SYSCFG_VDDIO2CCCR, 0, SYSCFG_CCCR_EN);

  /* Configure VDDIO3 (1.8V if fuse set, else 3.3V) */

  modifyreg32(STM32_PWR_CR11, 0, PWR_CR11_VDDIO3SV);
  if (getreg32(STM32_BSEC_OTP(BSEC_HW_CONFIG_ID)) & BSEC_HWS_HSLV_VDDIO3)
    {
      modifyreg32(STM32_PWR_CR11, 0, PWR_CR11_VDDIO3VRSEL);
    }

  modifyreg32(STM32_SYSCFG_VDDIO3CCCR, 0, SYSCFG_CCCR_EN);

  /* Configure VDDIO4 (3.3V) */

  modifyreg32(STM32_PWR_CR11, 0, PWR_CR11_VDDIO4SV);
  modifyreg32(STM32_SYSCFG_VDDIO4CCCR, 0, SYSCFG_CCCR_EN);

  /* Enable VDD for USB */

  modifyreg32(STM32_PWR_SVMCR3, 0, PWR_SVMCR3_VDDUSBSV);
}

/****************************************************************************
 * Name: fsbl_config_power
 *
 * Description:
 *   Configure SMPS supply and voltage scaling.
 *
 ****************************************************************************/

static void fsbl_config_power(void)
{
  /* Configure SMPS supply */

  modifyreg32(STM32_PWR_CR3, 0, PWR_CR3_SMPSLDOEN);

  /* Set voltage scaling to Scale 0 (highest performance) */

  modifyreg32(STM32_PWR_D3CR, PWR_D3CR_VOS_MASK, PWR_D3CR_VOS_SCALE1);
  while (!(getreg32(STM32_PWR_D3CR) & PWR_D3CR_VOSRDY))
    {
    }
}

/****************************************************************************
 * Name: xspi_pin_config
 *
 * Description:
 *   Configure XSPI2 pins (PN0-PN12) for flash access.
 *
 ****************************************************************************/

static void xspi_pin_config(void)
{
  /* Enable GPIO N clock */

  modifyreg32(STM32_RCC_AHB4ENSR, 0, RCC_AHB4ENSR_GPIONEN);

  /* Configure PN0-PN12 as AF9 (XSPI2), very high speed, no pull.
   * Each pin needs: MODER=AF, OSPEEDR=Very High, PUPDR=None, AFR=9
   */

  uint32_t moder = getreg32(STM32_GPIO_MODER(GPIOn_BASE));
  uint32_t ospeedr = getreg32(STM32_GPIO_OSPEEDR(GPIOn_BASE));
  uint32_t pupdr = getreg32(STM32_GPIO_PUPDR(GPIOn_BASE));
  uint32_t afrl = getreg32(STM32_GPIO_AFRL(GPIOn_BASE));
  uint32_t afrh = getreg32(STM32_GPIO_AFRH(GPIOn_BASE));

  for (int pin = 0; pin <= 12; pin++)
    {
      /* MODER: AF mode (0x2) */

      moder &= ~(3 << (pin * 2));
      moder |= (2 << (pin * 2));

      /* OSPEEDR: Very High speed (0x3) */

      ospeedr &= ~(3 << (pin * 2));
      ospeedr |= (3 << (pin * 2));

      /* PUPDR: No pull (0x0) */

      pupdr &= ~(3 << (pin * 2));

      /* AFR: AF9 */

      if (pin < 8)
        {
          afrl &= ~(15 << (pin * 4));
          afrl |= (XSPI2_AF << (pin * 4));
        }
      else
        {
          afrh &= ~(15 << ((pin - 8) * 4));
          afrh |= (XSPI2_AF << ((pin - 8) * 4));
        }
    }

  putreg32(moder, STM32_GPIO_MODER(GPIOn_BASE));
  putreg32(ospeedr, STM32_GPIO_OSPEEDR(GPIOn_BASE));
  putreg32(pupdr, STM32_GPIO_PUPDR(GPIOn_BASE));
  putreg32(afrl, STM32_GPIO_AFRL(GPIOn_BASE));
  putreg32(afrh, STM32_GPIO_AFRH(GPIOn_BASE));
}

/****************************************************************************
 * Name: xspi_write_111
 *
 * Description:
 *   Write data to flash using 1-1-1 SPI mode.
 *
 ****************************************************************************/

static void xspi_write_111(uint8_t cmd, uint32_t addr, bool addr_en,
                            const uint8_t *data, size_t len)
{
  uint32_t ccr = 1 << XSPI_CCR_DMODE_Pos  /* data on 1 line */
               | 3 << XSPI_CCR_ADSIZE_Pos  /* 32-bit address */
               | (addr_en ? 1 : 0) << XSPI_CCR_ADMODE_Pos
               | 1 << XSPI_CCR_IMODE_Pos;  /* instruction on 1 line */

  /* Indirect write mode */

  putreg32((getreg32(STM32_XSPI_CR) & ~XSPI_CR_FMODE) |
           (0 << XSPI_CR_FMODE_Pos), STM32_XSPI_CR);

  putreg32(ccr, STM32_XSPI_CCR);
  putreg32(0, STM32_XSPI_TCR);  /* no dummy cycles */

  if (len > 0)
    {
      putreg32(len - 1, STM32_XSPI_DLR);
    }

  putreg32(cmd, STM32_XSPI_IR);

  if (addr_en)
    {
      putreg32(addr, STM32_XSPI_AR);
    }

  /* Write data */

  while (len-- > 0)
    {
      while (!(getreg32(STM32_XSPI_SR) & XSPI_SR_FTF))
        {
        }

      putreg8(*data++, STM32_XSPI_DR);
    }

  /* Wait for completion */

  while (!(getreg32(STM32_XSPI_SR) & XSPI_SR_TCF))
    {
    }

  putreg32(XSPI_FCR_CTCF, STM32_XSPI_FCR);

  while (getreg32(STM32_XSPI_SR) & XSPI_SR_BUSY)
    {
    }
}

/****************************************************************************
 * Name: xspi_read_111
 *
 * Description:
 *   Read data from flash using 1-1-1 SPI mode.
 *
 ****************************************************************************/

static void xspi_read_111(uint8_t cmd, uint32_t addr, bool addr_en,
                           uint8_t *data, size_t len)
{
  uint32_t ccr = 1 << XSPI_CCR_DMODE_Pos  /* data on 1 line */
               | 3 << XSPI_CCR_ADSIZE_Pos  /* 32-bit address */
               | (addr_en ? 1 : 0) << XSPI_CCR_ADMODE_Pos
               | 1 << XSPI_CCR_IMODE_Pos;  /* instruction on 1 line */

  /* Indirect read mode */

  putreg32((getreg32(STM32_XSPI_CR) & ~XSPI_CR_FMODE) |
           (1 << XSPI_CR_FMODE_Pos), STM32_XSPI_CR);

  putreg32(ccr, STM32_XSPI_CCR);
  putreg32(0, STM32_XSPI_TCR);  /* no dummy cycles */
  putreg32(len - 1, STM32_XSPI_DLR);
  putreg32(cmd, STM32_XSPI_IR);

  if (addr_en)
    {
      putreg32(addr, STM32_XSPI_AR);
    }

  /* Read data */

  while (len-- > 0)
    {
      while (!((getreg32(STM32_XSPI_SR) >> XSPI_SR_FLEVEL_Pos) & 0x3f))
        {
        }

      *data++ = getreg8(STM32_XSPI_DR);
    }

  putreg32(XSPI_FCR_CTCF, STM32_XSPI_FCR);
}

/****************************************************************************
 * Name: xspi_write_888_dtr
 *
 * Description:
 *   Write data to flash using 8-8-8 DTR mode.
 *
 ****************************************************************************/

static void xspi_write_888_dtr(uint16_t cmd, uint32_t addr, bool addr_en,
                                const uint8_t *data, size_t len)
{
  uint32_t ccr = 1 << XSPI_CCR_DDTR_Pos   /* data DTR */
               | 4 << XSPI_CCR_DMODE_Pos   /* data on 8 lines */
               | 3 << XSPI_CCR_ADSIZE_Pos  /* 32-bit address */
               | 1 << XSPI_CCR_ADDTR_Pos   /* address DTR */
               | (addr_en ? 4 : 0) << XSPI_CCR_ADMODE_Pos
               | 1 << XSPI_CCR_ISIZE_Pos   /* 16-bit instruction */
               | 1 << XSPI_CCR_IDTR_Pos    /* instruction DTR */
               | 4 << XSPI_CCR_IMODE_Pos;  /* instruction on 8 lines */

  /* Indirect write mode */

  putreg32((getreg32(STM32_XSPI_CR) & ~XSPI_CR_FMODE) |
           (0 << XSPI_CR_FMODE_Pos), STM32_XSPI_CR);

  putreg32(ccr, STM32_XSPI_CCR);
  putreg32(0, STM32_XSPI_TCR);

  if (len > 0)
    {
      putreg32(len - 1, STM32_XSPI_DLR);
    }

  putreg32(cmd, STM32_XSPI_IR);

  if (addr_en)
    {
      putreg32(addr, STM32_XSPI_AR);
    }

  while (len-- > 0)
    {
      while (!(getreg32(STM32_XSPI_SR) & XSPI_SR_FTF))
        {
        }

      putreg8(*data++, STM32_XSPI_DR);
    }

  while (!(getreg32(STM32_XSPI_SR) & XSPI_SR_TCF))
    {
    }

  putreg32(XSPI_FCR_CTCF, STM32_XSPI_FCR);

  while (getreg32(STM32_XSPI_SR) & XSPI_SR_BUSY)
    {
    }
}

/****************************************************************************
 * Name: xspi_read_888_dtr
 *
 * Description:
 *   Read data from flash using 8-8-8 DTR mode.
 *
 ****************************************************************************/

static void xspi_read_888_dtr(uint16_t cmd, uint32_t addr, bool addr_en,
                               uint32_t dummy, uint8_t *data, size_t len)
{
  uint32_t ccr = 1 << XSPI_CCR_DQSE_Pos   /* DQS enabled */
               | 1 << XSPI_CCR_DDTR_Pos    /* data DTR */
               | 4 << XSPI_CCR_DMODE_Pos   /* data on 8 lines */
               | 3 << XSPI_CCR_ADSIZE_Pos  /* 32-bit address */
               | 1 << XSPI_CCR_ADDTR_Pos   /* address DTR */
               | (addr_en ? 4 : 0) << XSPI_CCR_ADMODE_Pos
               | 1 << XSPI_CCR_ISIZE_Pos   /* 16-bit instruction */
               | 1 << XSPI_CCR_IDTR_Pos    /* instruction DTR */
               | 4 << XSPI_CCR_IMODE_Pos;  /* instruction on 8 lines */

  /* Indirect read mode */

  putreg32((getreg32(STM32_XSPI_CR) & ~XSPI_CR_FMODE) |
           (1 << XSPI_CR_FMODE_Pos), STM32_XSPI_CR);

  putreg32(ccr, STM32_XSPI_CCR);
  putreg32(dummy << XSPI_TCR_DCYC_Pos, STM32_XSPI_TCR);
  putreg32(len - 1, STM32_XSPI_DLR);
  putreg32(cmd, STM32_XSPI_IR);

  if (addr_en)
    {
      putreg32(addr, STM32_XSPI_AR);
    }

  while (len-- > 0)
    {
      while (!((getreg32(STM32_XSPI_SR) >> XSPI_SR_FLEVEL_Pos) & 0x3f))
        {
        }

      *data++ = getreg8(STM32_XSPI_DR);
    }

  putreg32(XSPI_FCR_CTCF, STM32_XSPI_FCR);
}

/****************************************************************************
 * Name: xspi_switch_to_dtr
 *
 * Description:
 *   Switch the MX25UM25645G flash from SPI mode to DTR (DOPI) mode.
 *
 ****************************************************************************/

static void xspi_switch_to_dtr(void)
{
  uint8_t buf[4];

  /* Send WREN (Write Enable) */

  xspi_write_111(CMD_WREN, 0, false, NULL, 0);

  /* Wait for WEL bit */

  for (int i = 0; i < 100; i++)
    {
      xspi_read_111(CMD_RDSR, 0, false, buf, 1);
      if (buf[0] & 0x02)
        {
          break;
        }
    }

  /* Write Configuration Register 2 to switch to DOPI mode */

  buf[0] = 0x02;  /* DOPI mode */
  xspi_write_111(0x72, 0x00000000, true, buf, 1);
}

/****************************************************************************
 * Name: xspi_init
 *
 * Description:
 *   Initialize XSPI2 for flash access and enable memory-mapped mode.
 *
 ****************************************************************************/

static void xspi_init(void)
{
  /* Configure XSPI pins */

  xspi_pin_config();

  /* Enable XSPI clocks and release reset */

  modifyreg32(STM32_RCC_AHB5RSTSR, 0,
              RCC_AHB5RSTSR_XSPIMRSTS | RCC_AHB5RSTSR_XSPI2RSTS);
  modifyreg32(STM32_RCC_AHB5RSTCR, 0,
              RCC_AHB5RSTCR_XSPIMRSTC | RCC_AHB5RSTCR_XSPI2RSTC);

  modifyreg32(STM32_RCC_AHB5ENSR, 0,
              RCC_AHB5ENSR_XSPIMEN | RCC_AHB5ENSR_XSPI2EN);

  /* Set XSPI2 clock source to HCLK */

  modifyreg32(STM32_RCC_CCIPR4, RCC_CCIPR4_XSPI2SEL_MASK,
              RCC_CCIPR4_XSPI2SEL_HCLK);

  /* Configure XSPIM in direct mode */

  putreg32(0, STM32_XSPIM_CR);

  /* Disable XSPI2 for configuration */

  modifyreg32(STM32_XSPI_CR, XSPI_CR_EN, 0);

  /* Configure XSPI2:
   * - Macronix memory type
   * - 32MB flash size (28-3-1 = 24 bits for DEVSIZE)
   * - CS high time: 2 cycles
   * - CLK idles low
   * - Timeout counter enabled
   */

  putreg32((1 << XSPI_DCR1_MTYP_Pos) |
           ((XSPI_FLASH_SIZE_BITS_LOG2 - 3 - 1) << XSPI_DCR1_DEVSIZE_Pos) |
           (1 << XSPI_DCR1_CSHT_Pos) |
           (0 << XSPI_DCR1_CKMODE_Pos), STM32_XSPI_DCR1);

  /* Prescaler: F_CLK = F_AHB / 4 */

  putreg32((4 - 1) << XSPI_DCR2_PRESCALER_Pos, STM32_XSPI_DCR2);
  putreg32(0, STM32_XSPI_DCR3);
  putreg32(0, STM32_XSPI_DCR4);
  putreg32(0, STM32_XSPI_TCR);

  /* Enable XSPI2 */

  modifyreg32(STM32_XSPI_CR, 0, XSPI_CR_EN);

  /* Reconfigure XSPIM */

  modifyreg32(STM32_XSPI_CR, XSPI_CR_EN, 0);
  putreg32(0, STM32_XSPIM_CR);
  modifyreg32(STM32_XSPI_CR, 0, XSPI_CR_EN);

  /* Switch flash to DTR mode */

  xspi_switch_to_dtr();

  /* Enable memory-mapped mode (8DTRD) */

  xspi_memory_map_888();
}

/****************************************************************************
 * Name: xspi_memory_map_888
 *
 * Description:
 *   Enable memory-mapped mode for XIP using 8-8-8 DTR read.
 *
 ****************************************************************************/

static void xspi_memory_map_888(void)
{
  uint32_t ccr = 1 << XSPI_CCR_DQSE_Pos   /* DQS enabled */
               | 1 << XSPI_CCR_DDTR_Pos    /* data DTR */
               | 4 << XSPI_CCR_DMODE_Pos   /* data on 8 lines */
               | 3 << XSPI_CCR_ADSIZE_Pos  /* 32-bit address */
               | 1 << XSPI_CCR_ADDTR_Pos   /* address DTR */
               | 4 << XSPI_CCR_ADMODE_Pos  /* address on 8 lines */
               | 1 << XSPI_CCR_ISIZE_Pos   /* 16-bit instruction */
               | 1 << XSPI_CCR_IDTR_Pos    /* instruction DTR */
               | 4 << XSPI_CCR_IMODE_Pos;  /* instruction on 8 lines */

  putreg32(ccr, STM32_XSPI_CCR);
  putreg32(20 << XSPI_TCR_DCYC_Pos, STM32_XSPI_TCR);  /* 20 dummy cycles */
  putreg32(CMD_8DTRD, STM32_XSPI_IR);
  putreg32(1024, STM32_XSPI_LPTR);  /* timeout period */

  /* Enable memory-mapped mode */

  putreg32((getreg32(STM32_XSPI_CR) & ~XSPI_CR_FMODE) |
           (3 << XSPI_CR_FMODE_Pos), STM32_XSPI_CR);
}

/****************************************************************************
 * Name: fsbl_jump_to_app
 *
 * Description:
 *   Jump to the application at the given address.
 *
 ****************************************************************************/

static void fsbl_jump_to_app(uint32_t app_addr)
{
  uint32_t msp;
  uint32_t reset_handler;

  /* Validate application: check that the reset handler address is valid */

  msp = *(volatile uint32_t *)app_addr;
  reset_handler = *(volatile uint32_t *)(app_addr + 4);

  /* Check that MSP looks reasonable (in SRAM range) and reset handler
   * is in the XIP flash range
   */

  if ((msp & 0x2ff00000) != 0x20000000 ||
      (reset_handler & 0xff000000) != 0x70000000)
    {
      /* Invalid application, hang */

      for (; ; )
        {
        }
    }

  /* Set the vector table to the application's location */

  putreg32(app_addr, NVIC_VECTAB);

  /* Set MSP and jump */

  __asm__ volatile (
      "msr msp, %0\n"
      "bx %1\n"
      :
      : "r" (msp), "r" (reset_handler)
  );

  /* Should not reach here */

  for (; ; )
    {
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: fsbl_main
 *
 * Description:
 *   Main entry point for the FSBL.
 *
 ****************************************************************************/

int main(void)
{
  /* Disable interrupts */

  up_irq_disable();

  /* Configure VDD voltage domains */

  fsbl_config_vdd();

  /* Configure SMPS supply and voltage scaling */

  fsbl_config_power();

  /* Initialize XSPI flash and enable memory-mapped mode */

  xspi_init();

  /* Jump to the NuttX application */

  fsbl_jump_to_app(APPLICATION_ADDR);

  /* Should not reach here */

  return 0;
}

