/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: led_init
 *
 * Description:
 *   Initialize LED0 (PG10) for status indication.
 *   LED0 is active low (low = on, high = off).
 *
 ****************************************************************************/

static void led_init(void)
{
  uint32_t reg;
  uint32_t moder;
  uint32_t ospeedr;
  uint32_t pupdr;

  /* Enable GPIO G clock */

  reg = getreg32(STM32_RCC_AHB4ENSR);
  reg |= LED_RCC_EN;
  putreg32(reg, STM32_RCC_AHB4ENSR);

  /* Configure PG10 as general purpose output, very high speed, no pull */

  moder = getreg32(STM32_GPIOG_MODER);
  moder &= ~(3 << (LED_PIN * 2));
  moder |= (1 << (LED_PIN * 2));  /* Output mode (0x1) */
  putreg32(moder, STM32_GPIOG_MODER);

  ospeedr = getreg32(STM32_GPIOG_OSPEED);
  ospeedr &= ~(3 << (LED_PIN * 2));
  ospeedr |= (3 << (LED_PIN * 2));  /* Very high speed (0x3) */
  putreg32(ospeedr, STM32_GPIOG_OSPEED);

  pupdr = getreg32(STM32_GPIOG_PUPDR);
  pupdr &= ~(3 << (LED_PIN * 2));  /* No pull (0x0) */
  putreg32(pupdr, STM32_GPIOG_PUPDR);

  /* Start with LED off */

  LED_OFF();
}

/****************************************************************************
 * Name: led_blink
 *
 * Description:
 *   Blink LED0 a specified number of times.
 *   Each blink cycle is ~200ms on, ~200ms off.
 *
 ****************************************************************************/

static void led_blink(int count)
{
  for (int i = 0; i < count; i++)
    {
      LED_ON();
      fsbl_delay(2000000);
      LED_OFF();
      fsbl_delay(2000000);
    }
}

