  LED_OFF(); fsbl_delay(500000);
  LED_ON();  fsbl_delay(500000);
  LED_OFF(); fsbl_delay(500000);
  LED_ON();  fsbl_delay(500000);
  LED_OFF(); fsbl_delay(500000);

  /* Initialize XSPI flash and enable memory-mapped mode */

  xspi_init();

  /* Blink 4: Ready to jump */

  LED_ON();  fsbl_delay(500000);
  LED_OFF(); fsbl_delay(500000);
  LED_ON();  fsbl_delay(500000);
  LED_OFF(); fsbl_delay(500000);
  LED_ON();  fsbl_delay(500000);
  LED_OFF(); fsbl_delay(500000);
  LED_ON();  fsbl_delay(500000);
  LED_OFF(); fsbl_delay(500000);

  /* Turn LED on continuously - indicating ready to jump */

  LED_ON();

  /* Small delay so LED is visible */

  fsbl_delay(2000000);

  /* Jump to the NuttX application */

  fsbl_jump_to_app(APPLICATION_ADDR);

  /* Should not reach here */

  return 0;
}

