 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: fsbl_main
 *
 * Description:
 *   Main entry point for the FSBL.
 *
 ****************************************************************************/

int fsbl_main(int argc, char *argv[])
{
  /* Disable interrupts */

  up_irq_disable();

  /* Initialize LED for status indication */

  led_init();

  /* Blink 1: VDD configuration starts */

  LED_ON();  DELAY();
  LED_OFF(); DELAY();

  /* Configure VDD voltage domains */

  fsbl_config_vdd();

  /* Blink 2: Power configuration */

  LED_ON();  DELAY();
  LED_OFF(); DELAY();
  LED_ON();  DELAY();
  LED_OFF(); DELAY();

  /* Configure SMPS supply and voltage scaling */

  fsbl_config_power();

  /* Blink 3: XSPI initialization */

  LED_ON();  DELAY();
  LED_OFF(); DELAY();
  LED_ON();  DELAY();
  LED_OFF(); DELAY();
  LED_ON();  DELAY();
  LED_OFF(); DELAY();

  /* Initialize XSPI flash and enable memory-mapped mode */

  xspi_init();

  /* Blink 4: Ready to jump */

  LED_ON();  DELAY();
  LED_OFF(); DELAY();
  LED_ON();  DELAY();
  LED_OFF(); DELAY();
  LED_ON();  DELAY();
  LED_OFF(); DELAY();

