/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <sys/types.h>
#include <syslog.h>
#include <debug.h>

#include <nuttx/board.h>
#include <nuttx/leds/userled.h>

#include "dnn647.h"

#include <arch/board/board.h>

#include "arm_internal.h"
#include "hardware/stm32_gpio.h"
#include "hardware/stm32_rcc.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* LED1 on PE10 - active low */

#define LED1_GPIO_BASE   STM32_GPIOE_BASE
#define LED1_PIN         10

/* Simple delay - approximate at 600MHz */

#define DELAY() \
  do { \
    volatile uint32_t _i; \
    for (_i = 0; _i < 20000000; _i++); \
  } while (0)

/* LED control macros - active low */

#define LED1_ON()   putreg32((1 << (LED1_PIN + 16)), LED1_GPIO_BASE + STM32_GPIO_BSRR_OFFSET)
#define LED1_OFF()  putreg32((1 << LED1_PIN), LED1_GPIO_BASE + STM32_GPIO_BSRR_OFFSET)

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: app_led1_init
 *
 * Description:
 *   Initialize LED1 on PE10
 *
 ****************************************************************************/

static void app_led1_init(void)
{
  uint32_t regval;

  /* Enable GPIOE clock */

  modifyreg32(STM32_RCC_AHB4ENR, 0, RCC_AHB4ENR_GPIOEEN);

  /* Wait for clock to stabilize */

  volatile int i;
  for (i = 0; i < 1000; i++);

  /* Configure PE10 as general purpose output, push-pull, low speed */

  regval = getreg32(LED1_GPIO_BASE + STM32_GPIO_MODER_OFFSET);
  regval &= ~(3 << (LED1_PIN * 2));
  regval |= (1 << (LED1_PIN * 2));  /* Output mode */
  putreg32(regval, LED1_GPIO_BASE + STM32_GPIO_MODER_OFFSET);

  /* Push-pull output type (default) */

  regval = getreg32(LED1_GPIO_BASE + STM32_GPIO_OTYPER_OFFSET);
  regval &= ~(1 << LED1_PIN);
  putreg32(regval, LED1_GPIO_BASE + STM32_GPIO_OTYPER_OFFSET);

  /* Low speed */

  regval = getreg32(LED1_GPIO_BASE + STM32_GPIO_OSPEEDR_OFFSET);
  regval &= ~(3 << (LED1_PIN * 2));
  putreg32(regval, LED1_GPIO_BASE + STM32_GPIO_OSPEEDR_OFFSET);

  /* No pull-up/pull-down */

  regval = getreg32(LED1_GPIO_BASE + STM32_GPIO_PUPDR_OFFSET);
  regval &= ~(3 << (LED1_PIN * 2));
  putreg32(regval, LED1_GPIO_BASE + STM32_GPIO_PUPDR_OFFSET);

  /* Start with LED1 off (HIGH = off for active low) */

  LED1_OFF();
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: stm32_bringup
 *
 * Description:
 *   Perform architecture-specific initialization
 *
 *   CONFIG_BOARD_LATE_INITIALIZE=y :
 *     Called from board_late_initialize().
 *
 *   CONFIG_BOARD_LATE_INITIALIZE=n && CONFIG_BOARDCTL=y :
 *     Called from the NSH library
 *
 ****************************************************************************/

int stm32_bringup(void)
{
#if !defined(CONFIG_ARCH_LEDS) && defined(CONFIG_USERLED_LOWER)
  int ret;

  /* Register the LED driver */

  ret = userled_lower_initialize("/dev/userleds");
  if (ret < 0)
    {
      syslog(LOG_ERR, "ERROR: userled_lower_initialize() failed: %d\n", ret);
    }
#endif

  /* Initialize LED1 and start blinking to indicate app is running */

  app_led1_init();

  /* Blink LED1 continuously to indicate NuttX app is running */

  for (; ; )
    {
      LED1_ON();
      DELAY();
      LED1_OFF();
      DELAY();
    }

  return OK;
}

