1	/*
2	******************************************************************************
3	**
4	** @file        : STM32N6XX_AXISRAM2_fsbl.ld
5	**
6	** @author      : GPM Application Team
7	**
8	** @brief       : Linker script for STM32N6XX Device from STM32N6 series
9	**                      512 KBytes RAM
10	**
11	**                Set heap size, stack size and stack location according
12	**                to application requirements.
13	**
14	**                Set memory bank area and size if external memory is used
15	**
16	**  Target      : STMicroelectronics STM32
17	**
18	**  Distribution: The file is distributed as is, without any warranty
19	**                of any kind.
20	**
21	******************************************************************************
22	** @attention
23	**
24	** Copyright (c) 2026 STMicroelectronics.
25	** All rights reserved.
26	**
27	** This software is licensed under terms that can be found in the LICENSE file
28	** in the root directory of this software component.
29	** If no LICENSE file comes with this software, it is provided AS-IS.
30	**
31	******************************************************************************
32	*/
33	
34	/* Entry Point */
35	ENTRY(Reset_Handler)
36	
37	/* Highest address of the user mode stack */
38	_estack = ORIGIN(RAM) + LENGTH(RAM); /* end of "RAM" Ram type memory */
39	_sstack = _estack - _Min_Stack_Size;
40	
41	_Min_Heap_Size = 0x200; /* required amount of heap */
42	_Min_Stack_Size = 0x800; /* required amount of stack */
43	
44	/* Memories definition */
45	MEMORY
46	{
47	  ROM    (xrw)    : ORIGIN = 0x34180400,   LENGTH = 255K
48	  RAM    (xrw)    : ORIGIN = 0x341C0000,   LENGTH = 256K
49	}
50	
51	/* Sections */
52	SECTIONS
53	{
54	  /* The startup code into "ROM" Rom type memory */
55	  .isr_vector :
56	  {
57	    . = ALIGN(4);
58	    KEEP(*(.isr_vector)) /* Startup code */
59	    . = ALIGN(4);
60	  } >ROM
61	
62	  /* The program code and other data into "ROM" Rom type memory */
63	  .text :
64	  {
65	    . = ALIGN(4);
66	    *(.text)           /* .text sections (code) */
67	    *(.text*)          /* .text* sections (code) */
68	    *(.glue_7)         /* glue arm to thumb code */
69	    *(.glue_7t)        /* glue thumb to arm code */
70	    *(.eh_frame)
71	    *(.RamFunc)        /* .RamFunc sections */
72	    *(.RamFunc*)       /* .RamFunc* sections */
73	
74	    KEEP (*(.init))
75	    KEEP (*(.fini))
76	
77	    . = ALIGN(4);
78	    _etext = .;        /* define a global symbols at end of code */
79	  } >ROM
80	
81	  /* Constant data into "ROM" Rom type memory */
82	  .rodata :
83	  {
84	    . = ALIGN(4);
85	    *(.rodata)         /* .rodata sections (constants, strings, etc.) */
86	    *(.rodata*)        /* .rodata* sections (constants, strings, etc.) */
87	    . = ALIGN(4);
88	  } >ROM
89	
90	  .ARM.extab   (READONLY) : /* The READONLY keyword is only supported in GCC11 and later, remove it if using GCC10 or earlier. */
91	   {
92	    . = ALIGN(4);
93	    *(.ARM.extab* .gnu.linkonce.armextab.*)
94	    . = ALIGN(4);
95	  } >ROM
96	
97	  .ARM (READONLY) : /* The READONLY keyword is only supported in GCC11 and later, remove it if using GCC10 or earlier. */
98	   {
99	    . = ALIGN(4);
100	    __exidx_start = .;
101	    *(.ARM.exidx*)
102	    __exidx_end = .;
103	    . = ALIGN(4);
104	  } >ROM
105	
106	  .preinit_array     (READONLY) : /* The READONLY keyword is only supported in GCC11 and later, remove it if using GCC10 or earlier. */
107	  {
108	    . = ALIGN(4);
109	    PROVIDE_HIDDEN (__preinit_array_start = .);
110	    KEEP (*(.preinit_array*))
111	    PROVIDE_HIDDEN (__preinit_array_end = .);
112	    . = ALIGN(4);
113	  } >ROM
114	
115	  .init_array (READONLY) : /* The READONLY keyword is only supported in GCC11 and later, remove it if using GCC10 or earlier. */
116	  {
117	    . = ALIGN(4);
118	    PROVIDE_HIDDEN (__init_array_start = .);
119	    KEEP (*(SORT(.init_array.*)))
120	    KEEP (*(.init_array*))
121	    PROVIDE_HIDDEN (__init_array_end = .);
122	    . = ALIGN(4);
123	  } >ROM
124	
125	  .fini_array (READONLY) : /* The READONLY keyword is only supported in GCC11 and later, remove it if using GCC10 or earlier. */
126	  {
127	    . = ALIGN(4);
128	    PROVIDE_HIDDEN (__fini_array_start = .);
129	    KEEP (*(SORT(.fini_array.*)))
130	    KEEP (*(.fini_array*))
131	    PROVIDE_HIDDEN (__fini_array_end = .);
132	    . = ALIGN(4);
133	  } >ROM
134	
135	  /* Used by the startup to initialize data */
136	  _sidata = LOADADDR(.data);
137	
138	  /* Initialized data sections into "RAM" Ram type memory */
139	  .data :
140	  {
141	    . = ALIGN(4);
142	    _sdata = .;        /* create a global symbol at data start */
143	    *(.data)           /* .data sections */
144	    *(.data*)          /* .data* sections */
145	
146	    . = ALIGN(4);
147	    _edata = .;        /* define a global symbol at data end */
148	
149	  } >RAM AT> ROM
150	
151	  .noncacheable :
152	  {
153	    . = ALIGN(8);
154	    __snoncacheable = .;/* create symbol for start of section */
155	    KEEP(*(.noncacheable))
156	    . = ALIGN(8);
157	    __enoncacheable = .;  /* create symbol for end of section */
158	  } > RAM
159	
160	
161	  .gnu.sgstubs :
162	  {
163	    . = ALIGN(4);
164	    *(.gnu.sgstubs*)   /* Secure Gateway stubs */
165	    . = ALIGN(4);
166	  } >ROM
167	  /* Uninitialized data section into "RAM" Ram type memory */
168	  . = ALIGN(4);
169	  .bss :
170	  {
171	    /* This is used by the startup in order to initialize the .bss section */
172	    _sbss = .;         /* define a global symbol at bss start */
173	    __bss_start__ = _sbss;
174	    *(.bss)
175	    *(.bss*)
176	    *(COMMON)
177	
178	    . = ALIGN(4);
179	    _ebss = .;         /* define a global symbol at bss end */
180	    __bss_end__ = _ebss;
181	  } >RAM
182	
183	  /* User_heap_stack section, used to check that there is enough "RAM" Ram  type memory left */
184	  ._user_heap_stack :
185	  {
186	    . = ALIGN(8);
187	    PROVIDE ( end = . );
188	    PROVIDE ( _end = . );
189	    . = . + _Min_Heap_Size;
190	    . = . + _Min_Stack_Size;
191	    . = ALIGN(8);
192	  } >RAM
193	
194	  /* Remove information from the compiler libraries */
195	  /DISCARD/ :
196	  {
197	    libc.a ( * )
198	    libm.a ( * )
199	    libgcc.a ( * )
200	  }
201	
202	  .ARM.attributes 0 : { *(.ARM.attributes) }
203	}
