 * Board Stubs - minimal implementations for FSBL
 ****************************************************************************/

/* Board initialization stub */

void stm32_board_initialize(void)
{
  /* Nothing to do for FSBL */
}

/* LED stubs */

void board_autoled_on(int led)
{
  (void)led;
}

void board_autoled_off(int led)
{
  (void)led;
