#include <arch/board/board.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Simple delay - approximate at 600MHz */

#define DELAY() \
  do { \
    volatile uint32_t _i; \
    for (_i = 0; _i < 20000000; _i++); \
  } while (0)

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: stm32_bringup
 *
 * Description:
 *   Perform architecture-specific initialization
 *
 *   CONFIG_BOARD_LATE_INITIALIZE=y :
 *     Called from board_late_initialize().
 *
 *   CONFIG_BOARD_LATE_INITIALIZE=n && CONFIG_BOARDCTL=y :
 *     Called from the NSH library
 *
 ****************************************************************************/

int stm32_bringup(void)
{
#if !defined(CONFIG_ARCH_LEDS) && defined(CONFIG_USERLED_LOWER)
  int ret;

  /* Register the LED driver */

  ret = userled_lower_initialize("/dev/userleds");
  if (ret < 0)
    {
      syslog(LOG_ERR, "ERROR: userled_lower_initialize() failed: %d\n", ret);
    }
#endif

  /* Configure LED1 (PE10) as output using NuttX GPIO API */

  stm32_configgpio(GPIO_LED1);

  /* Turn off LED1 initially (active low, so HIGH = off) */

  stm32_gpiowrite(GPIO_LED1, true);

  /* Blink LED1 continuously to indicate NuttX app is running */

  for (; ; )
    {
      stm32_gpiowrite(GPIO_LED1, false);  /* LED1 ON (active low) */
      DELAY();
      stm32_gpiowrite(GPIO_LED1, true);   /* LED1 OFF (active low) */
      DELAY();
    }

  return OK;
}

