58	  * @retval BOOTStatus_TypeDef Status of the operation.
59	  */
60	BOOTStatus_TypeDef BOOT_Application(void)
61	{
62	  BOOTStatus_TypeDef retr;
63	
64	  /* Mount the memory */
65	  retr = MapMemory();
66	  if (BOOT_OK == retr)
67	  {
