91	  /* Map all the memory */
92	  for (uint8_t index = 0; index < (sizeof(extmem_list_config) / sizeof(EXTMEM_DefinitionTypeDef)); index++)
93	  {
94	    switch (EXTMEM_MemoryMappedMode(index, EXTMEM_ENABLE))
95	    {
96	      case EXTMEM_ERROR_NOTSUPPORTED :
97	        if (EXTMEM_MEMORY_BOOTXIP ==  index)
98	        {
99	          retr = BOOT_ERROR_INCOMPATIBLEMEMORY;
100	        }
101	        else
102	        {
