123	  typedef  void (*pFunction)(void);
124	  static pFunction JumpToApp;
125	  uint32_t Application_vector;
126	
127	  if (EXTMEM_OK != EXTMEM_GetMapAddress(EXTMEM_MEMORY_BOOTXIP, &Application_vector))
128	  {
129	    return BOOT_ERROR_INCOMPATIBLEMEMORY;
130	  }
131	
132	  /* Suspend SysTick */
133	  HAL_SuspendTick();
134	
135	#if defined(__ICACHE_PRESENT) && (__ICACHE_PRESENT == 1U)
136	  /* if I-Cache is enabled, disable I-Cache-----------------------------------*/
137	  if (SCB->CCR & SCB_CCR_IC_Msk)
138	  {
