143	#if defined(__DCACHE_PRESENT) && (__DCACHE_PRESENT == 1U)
144	  /* if D-Cache is enabled, disable D-Cache-----------------------------------*/
145	  if (SCB->CCR & SCB_CCR_DC_Msk)
146	  {
147	    SCB_DisableDCache();
148	  }
149	#endif /* __DCACHE_PRESENT */
150	
151	  /* Initialize user application's Stack Pointer & Jump to user application  */
152	  primask_bit = __get_PRIMASK();
153	  __disable_irq();
154	
155	  /* Apply offsets for image location and vector table offset */
156	  Application_vector += EXTMEM_XIP_IMAGE_OFFSET + EXTMEM_HEADER_OFFSET;
157	
158	  SCB->VTOR = (uint32_t)Application_vector;
159	  JumpToApp = (pFunction)(*(__IO uint32_t *)(Application_vector + 4u));
160	
161	#if (defined(__ARM_ARCH_8M_MAIN__ ) && (__ARM_ARCH_8M_MAIN__ == 1))
162	  /* on ARM v8m, set MSPLIM before setting MSP to avoid unwanted stack overflow faults */
163	  __set_MSPLIM(0x00000000);
164	#elif (defined(__ARM_ARCH_8_1M_MAIN__ ) && (__ARM_ARCH_8_1M_MAIN__ == 1))
165	  /* on ARM v8m, set MSPLIM before setting MSP to avoid unwanted stack overflow faults */
166	  __set_MSPLIM(0x00000000);
167	#elif (defined(__ARM_ARCH_8M_BASE__ ) && (__ARM_ARCH_8M_BASE__ == 1))
168	  /* on ARM v8m, set MSPLIM before setting MSP to avoid unwanted stack overflow faults */
169	  __set_MSPLIM(0x00000000);
170	#endif  /* __ARM_ARCH_8M_MAIN__ or __ARM_ARCH_8_1M_MAIN__ or __ARM_ARCH_8M_BASE__ */
171	
172	  __set_MSP(*(__IO uint32_t *) Application_vector);
173	
174	  /* Re-enable the interrupts */
175	  __set_PRIMASK(primask_bit);
176	
177	  JumpToApp();
178	  return BOOT_OK;
179	}
