1	/**
2	  ******************************************************************************
3	  * @file    system_stm32n6xx_s.c
4	  * @author  MCD Application Team
5	  * @brief   CMSIS Cortex-M55 Device Peripheral Access Layer System Source File
6	  *          to be used in secure application.
7	  *
8	  *   This file provides two functions and one global variable to be called from
9	  *   user application:
10	  *      - SystemInit(): This function is called at secure startup just after reset
11	  *                      and before branch to secure main program.
12	  *                      This call is made inside the "startup_stm32n6xx.s" file.
13	  *
14	  *      - SystemCoreClock variable: Contains the CPU core clock, it can be used
15	  *                                  by the user application to setup the SysTick
16	  *                                  timer or configure other parameters.
17	  *
18	  *      - SystemCoreClockUpdate(): Updates the variable SystemCoreClock and must
19	  *                                 be called whenever the core clock is changed
20	  *                                 during program execution.
21	  *
22	  *      - SECURE_SystemCoreClockUpdate(): Non-secure callable function to update
23	  *                                        the variable SystemCoreClock and return
24	  *                                        its value to the non-secure calling
25	  *                                        application. It must be called whenever
26	  *                                        the core clock is changed during program
27	  *                                        execution.
28	  *
29	  *   After each device reset the HSI (64 MHz) is used as system clock source.
30	  *   Then SystemInit() function is called, in "startup_stm32n6xx.s" file, to
31	  *   configure the system before to branch to main program.
32	  *
33	  ******************************************************************************
34	  * @attention
35	  *
36	  * Copyright (c) 2023 STMicroelectronics.
37	  * All rights reserved.
38	  *
39	  * This software is licensed under terms that can be found in the LICENSE file
40	  * in the root directory of this software component.
41	  * If no LICENSE file comes with this software, it is provided AS-IS.
42	  *
43	  ******************************************************************************
44	  */
45	
46	/** @addtogroup CMSIS
47	  * @{
48	  */
49	
50	/** @addtogroup STM32N6xx_System
51	  * @{
52	  */
53	
54	/** @addtogroup STM32N6xx_System_Private_Includes
55	  * @{
56	  */
57	
58	#include "stm32n6xx.h"
59	#include "partition_stm32n6xx.h"  /* Trustzone-M core secure attributes */
60	#include <math.h>
61	
62	/**
63	  * @}
64	  */
65	
66	/** @addtogroup STM32N6xx_System_Private_TypesDefinitions
67	  * @{
68	  */
69	
70	#if defined ( __ICCARM__ )
71	#  define CMSE_NS_ENTRY __cmse_nonsecure_entry
72	#else
73	#  define CMSE_NS_ENTRY __attribute((cmse_nonsecure_entry))
74	#endif
75	
76	/**
77	  * @}
78	  */
79	
80	/** @addtogroup STM32N6xx_System_Private_Defines
81	  * @{
82	  */
83	#if !defined  (HSE_VALUE)
84	#define HSE_VALUE      48000000UL /*!< Value of the High-Speed External oscillator in Hz */
85	#endif /* HSE_VALUE */
86	
87	#if !defined  (HSI_VALUE)
88	#define HSI_VALUE      64000000UL /*!< Value of the High-Speed Internal oscillator in Hz */
89	#endif /* HSI_VALUE */
90	
91	#if !defined  (MSI_VALUE)
92	  #define MSI_VALUE       4000000UL /*!< Minimum value of the Low-power Internal oscillator in Hz */
93	#endif /* MSI_VALUE */
94	
95	#if !defined  (EXTERNAL_I2S_CLOCK_VALUE)
96	  #define EXTERNAL_I2S_CLOCK_VALUE  12288000UL /*!< Value of the External clock for I2S_CKIN in Hz */
97	#endif /* EXTERNAL_I2S_CLOCK_VALUE */
98	
99	
100	/* Note: Following vector table addresses must be defined in line with linker
101	         configuration. */
102	/*!< Uncomment the following line if you need to relocate the vector table
103	     anywhere in memory, else the vector table is kept at the automatic
104	     selected boot address */
105	/* #define USER_VECT_TAB_ADDRESS */
106	
107	#if defined(USER_VECT_TAB_ADDRESS)
108	#if !defined(VECT_TAB_BASE_ADDRESS)
109	#define VECT_TAB_BASE_ADDRESS   SRAM1_AXI_BASE_S /*!< Vector Table base address field.
110	                                                     This value must be a multiple of 0x400. */
111	#endif
112	
113	#if !defined(VECT_TAB_OFFSET)
114	#define VECT_TAB_OFFSET         0x00000000U     /*!< Vector Table base offset field.
115	                                                     This value must be a multiple of 0x400. */
116	#endif
117	#endif /* USER_VECT_TAB_ADDRESS */
118	
119	/******************************************************************************/
120	/**
121	  * @}
122	  */
123	
124	/** @addtogroup STM32N6xx_System_Private_Macros
125	  * @{
126	  */
127	
128	/**
129	  * @}
130	  */
131	
132	/** @addtogroup STM32N6xx_System_Private_Variables
133	  * @{
134	  */
135	  /* The SystemCoreClock variable is updated in three ways:
136	      1) by calling CMSIS function SystemCoreClockUpdate()
137	      2) by calling HAL API function HAL_RCC_GetHCLKFreq()
138	      3) each time HAL_RCC_ClockConfig() is called to configure the system clock frequency
139	         Note: If you use this function to configure the system clock; then there
140	               is no need to call the 2 first functions listed above, since SystemCoreClock
141	               variable is updated automatically.
142	  */
143	uint32_t SystemCoreClock = HSI_VALUE;
144	/**
145	  * @}
146	  */
147	
148	/** @addtogroup STM32N6xx_System_Private_FunctionPrototypes
149	  * @{
150	  */
151	
