/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: fsbl_main
 *
 * Description:
 *   Main entry point for the FSBL.
 *
 ****************************************************************************/

int fsbl_main(int argc, char *argv[])
{
  /* Disable interrupts */

  up_irq_disable();

  /* Enable PWR clock first (needed for VDD configuration) */

  modifyreg32(STM32_RCC_AHB4ENSR, 0, (1 << 16));  /* PWREN */

  /* Enable VDDIO4 (3.3V) for GPIO G */

  modifyreg32(STM32_PWR_SVMCR1, 0, PWR_SVMCR1_VDDIO4SV);

  /* Now initialize LED for status indication */

  led_init();

  /* Step 1: LED on - PWR and VDDIO4 configured */

  LED_ON();
  DELAY(); DELAY(); DELAY(); DELAY(); DELAY();  /* ~1 second */

  /* Step 2: Configure VDD */

  fsbl_config_vdd();

  /* If we get here, blink LED twice */

  LED_OFF(); DELAY();
  LED_ON();  DELAY();
  LED_OFF(); DELAY();
  LED_ON();  DELAY();

  /* Step 3: Configure power */

  fsbl_config_power();

  /* If we get here, blink LED three times */

  LED_OFF(); DELAY();
  LED_ON();  DELAY();
  LED_OFF(); DELAY();
  LED_ON();  DELAY();
  LED_OFF(); DELAY();
  LED_ON();  DELAY();

  /* Step 4: Initialize XSPI */

  xspi_init();

  /* If we get here, LED stays on */

  LED_ON();

  /* Wait before jumping */

  DELAY(); DELAY(); DELAY(); DELAY(); DELAY();

  /* Jump to the NuttX application */

  fsbl_jump_to_app(APPLICATION_ADDR);

  /* Should not reach here */

  return 0;
}

